-- NBL National Cup knockout bracket
--
-- Basketball England publishes the whole draw as a numbered tree (G1 … G127), so the shape
-- is saved once here and results are filled in as they come (see server/nationalCup.ts and
-- shared/nationalCup.ts). A side is either named on the row, or "winner of game N" through
-- home_from / away_from. Seeded below with the men's draw as published on 2026-10-05, with
-- Round 1 and Round of 64 results.
--
-- Public read, like the schedule: the bracket is meant to be seen by everyone. Only the
-- server (service key) writes it, so there are no insert/update policies.

CREATE TABLE IF NOT EXISTS public.cup_bracket_games (
  league_id   uuid NOT NULL REFERENCES public.competitions (league_id) ON DELETE CASCADE,
  game_no     integer NOT NULL CHECK (game_no BETWEEN 1 AND 255),
  round       text NOT NULL CHECK (round IN ('R1', 'R64', 'R32', 'R16', 'QF', 'SF', 'F')),
  game_date   date,
  tip_time    text,                          -- UK local time as shown on the Basketball England site
  home_name   text,
  away_name   text,
  home_from   integer,                       -- game whose winner plays at home, while home_name is empty
  away_from   integer,
  is_bye      boolean NOT NULL DEFAULT false,
  home_score  integer CHECK (home_score IS NULL OR home_score >= 0),
  away_score  integer CHECK (away_score IS NULL OR away_score >= 0),
  forfeit     boolean NOT NULL DEFAULT false,
  report_id   text,
  scraped_at  timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (league_id, game_no)
);

ALTER TABLE public.cup_bracket_games ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS cup_bracket_games_public_read ON public.cup_bracket_games;
CREATE POLICY cup_bracket_games_public_read ON public.cup_bracket_games
  FOR SELECT TO anon, authenticated USING (true);

GRANT SELECT ON public.cup_bracket_games TO anon, authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.cup_bracket_games FROM anon, authenticated;

-- Men's National Cup 2026-27 (competition nbl-mens-national-cup-26-27)
ON CONFLICT (league_id, game_no) DO NOTHING;
